1	"use client";
2	
3	import { useRef, useState } from "react";
4	import Link from "next/link";
5	import { trackEvent } from "@/lib/analytics/google-analytics";
6	
7	type Ingredient = { id: string; name: string; cost: string };
8	
9	function formatRupiah(value: number) {
10	  if (!Number.isFinite(value)) return "Rp0";
11	  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
12	}
13	
14	function makeIngredient(name = "", cost = ""): Ingredient {
15	  return { id: crypto.randomUUID(), name, cost };
16	}
17	
18	export function HppCalculator() {
19	  const [ingredients, setIngredients] = useState<Ingredient[]>(() => [
20	    makeIngredient("Nasi 1 porsi", "2500"),
21	    makeIngredient("Telur 1 butir", "2000"),
22	    makeIngredient("Ayam suwir 50gr", "4000"),
23	    makeIngredient("Bumbu & minyak", "1500"),
24	  ]);
25	  const [portions, setPortions] = useState("1");
26	  const [marginPercent, setMarginPercent] = useState("60");
27	  const trackedRef = useRef(false);
28	
29	  const totalCost = ingredients.reduce((sum, ing) => sum + (parseFloat(ing.cost) || 0), 0);
30	  const portionCount = Math.max(parseFloat(portions) || 1, 1);
31	  const hppPerPortion = totalCost / portionCount;
32	  const margin = Math.min(Math.max(parseFloat(marginPercent) || 0, 0), 95);
33	  const suggestedPrice = hppPerPortion / (1 - margin / 100);
34	  const grossProfit = suggestedPrice - hppPerPortion;
35	
36	  function trackFirstUse() {
37	    if (!trackedRef.current) {
38	      trackedRef.current = true;
39	      trackEvent("hpp_calculator_used");
40	    }
41	  }
42	
43	  function updateIngredient(id: string, field: "name" | "cost", value: string) {
44	    trackFirstUse();
45	    setIngredients((prev) => prev.map((ing) => (ing.id === id ? { ...ing, [field]: value } : ing)));
46	  }
47	
48	  function addIngredient() {
49	    trackFirstUse();
50	    setIngredients((prev) => [...prev, makeIngredient()]);
51	  }
52	
53	  function removeIngredient(id: string) {
54	    setIngredients((prev) => prev.filter((ing) => ing.id !== id));
55	  }
56	
57	  return (
58	    <div className="grid gap-6 lg:grid-cols-5">
59	      <div className="rounded-2xl border border-zinc-200 bg-white p-6 shadow-sm lg:col-span-3">
60	        <p className="text-sm font-bold text-zinc-900">Bahan & Biaya per Porsi</p>
61	        <div className="mt-4 space-y-2">
62	          {ingredients.map((ing) => (
63	            <div key={ing.id} className="flex items-center gap-2">
64	              <input
65	                type="text"
66	                value={ing.name}
67	                onChange={(e) => updateIngredient(ing.id, "name", e.target.value)}
68	                placeholder="Nama bahan"
69	                className="flex-1 rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
70	              />
71	              <input
72	                type="number"
73	                inputMode="numeric"
74	                value={ing.cost}
75	                onChange={(e) => updateIngredient(ing.id, "cost", e.target.value)}
76	                placeholder="Biaya (Rp)"
77	                className="w-28 rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none sm:w-32"
78	              />
79	              <button
80	                type="button"
81	                onClick={() => removeIngredient(ing.id)}
82	                className="shrink-0 rounded-lg px-2 py-2 text-zinc-400 transition-colors hover:bg-zinc-50 hover:text-red-500"
83	                aria-label="Hapus bahan"
84	              >
85	                ✕
86	              </button>
87	            </div>
88	          ))}
89	        </div>
90	        <button
91	          type="button"
92	          onClick={addIngredient}
93	          className="mt-3 text-xs font-semibold text-brand-700 hover:underline"
94	        >
95	          + Tambah Bahan
96	        </button>
97	
98	        <div className="mt-6 grid grid-cols-2 gap-4 border-t border-zinc-100 pt-6">
99	          <div>
100	            <label className="text-xs font-semibold text-zinc-500">Jumlah Porsi Dihasilkan</label>
101	            <input
102	              type="number"
103	              inputMode="numeric"
104	              min="1"
105	              value={portions}
106	              onChange={(e) => {
107	                trackFirstUse();
108	                setPortions(e.target.value);
109	              }}
110	              className="mt-1 w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
111	            />
112	          </div>
113	          <div>
114	            <label className="text-xs font-semibold text-zinc-500">Target Margin Kotor (%)</label>
115	            <input
116	              type="number"
117	              inputMode="numeric"
118	              min="0"
119	              max="95"
120	              value={marginPercent}
121	              onChange={(e) => {
122	                trackFirstUse();
123	                setMarginPercent(e.target.value);
124	              }}
125	              className="mt-1 w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none"
126	            />
127	          </div>
128	        </div>
129	      </div>
130	
131	      <div className="space-y-3 lg:col-span-2">
132	        <div className="rounded-2xl bg-zinc-900 p-6 text-white shadow-lg">
133	          <p className="text-xs font-semibold uppercase tracking-wide text-zinc-400">HPP per Porsi</p>
134	          <p className="mt-1 text-3xl font-bold">{formatRupiah(hppPerPortion)}</p>
135	          <p className="mt-1 text-xs text-zinc-400">Total biaya bahan: {formatRupiah(totalCost)}</p>
136	        </div>
137	
138	        <div className="rounded-2xl border-2 border-brand-500 bg-brand-50 p-6">
139	          <p className="text-xs font-semibold uppercase tracking-wide text-brand-700">
140	            Harga Jual Disarankan
141	          </p>
142	          <p className="mt-1 text-3xl font-bold text-brand-700">{formatRupiah(suggestedPrice)}</p>
143	          <p className="mt-1 text-xs text-brand-600">
144	            Margin kotor: {formatRupiah(grossProfit)} ({margin}%)
145	          </p>
146	        </div>
147	
148	        <div className="rounded-2xl bg-gradient-to-br from-brand-700 via-brand-600 to-emerald-600 p-6 text-white shadow-lg">
149	          <p className="text-sm font-bold">Capek Hitung Ulang Tiap Harga Bahan Naik?</p>
150	          <p className="mt-1.5 text-xs leading-relaxed text-brand-50/90">
151	            KasirKu menghitung HPP setiap produk otomatis dari resepnya — begitu harga satu bahan
152	            berubah, semua produk yang memakainya ikut ter-update sendiri.
153	          </p>
154	          <Link
155	            href="/signup"
156	            onClick={() => trackEvent("hpp_calculator_cta_click")}
157	            className="mt-4 inline-block rounded-xl bg-white px-5 py-2.5 text-sm font-semibold text-brand-700 shadow-md transition-colors hover:bg-brand-50"
158	          >
159	            Coba KasirKu Gratis →
160	          </Link>
161	        </div>
162	      </div>
163	    </div>
164	  );
165	}
