5	export default async function HppCalculatorPage({
6	  params,
7	}: {
8	  params: Promise<{ businessId: string }>;
9	}) {
10	  const { businessId } = await params;
11	  const supabase = await createClient();
12	
13	  const { data: business } = await supabase
14	    .from("businesses")
15	    .select("id, name")
16	    .eq("id", businessId)
17	    .single();
18	
19	  if (!business) {
20	    notFound();
21	  }
22	
23	  const { data: products } = await supabase
24	    .from("products")
25	    .select("id, name, price, cost")
26	    .eq("business_id", businessId)
27	    .is("deleted_at", null)
28	    .order("name", { ascending: true });
29	
30	  const productIds = (products ?? []).map((p) => p.id);
31	
32	  let recipeRows: {
33	    product_id: string;
34	    qty: number;
35	    unit: string;
36	    ingredients: { name: string; unit_cost: number } | null;
37	  }[] = [];
38	
39	  if (productIds.length > 0) {
40	    const { data } = await supabase
41	      .from("product_recipes")
42	      .select("product_id, qty, unit, ingredients(name, unit_cost)")
43	      .in("product_id", productIds);
44	    recipeRows = (data ?? []) as unknown as typeof recipeRows;
45	  }
46	
47	  const recipesByProduct = new Map<
48	    string,
49	    { name: string; qty: number; unit: string; unitCost: number; lineCost: number }[]
50	  >();
51	  for (const r of recipeRows) {
52	    const list = recipesByProduct.get(r.product_id) ?? [];
53	    const unitCost = Number(r.ingredients?.unit_cost ?? 0);
54	    list.push({
55	      name: r.ingredients?.name ?? "Bahan terhapus",
56	      qty: Number(r.qty),
57	      unit: r.unit,
58	      unitCost,
59	      lineCost: unitCost * Number(r.qty),
60	    });
61	    recipesByProduct.set(r.product_id, list);
62	  }
63	
64	  const menuItems = (products ?? []).map((p) => ({
65	    id: p.id,
66	    name: p.name,
67	    price: Number(p.price),
68	    cost: Number(p.cost),
69	    ingredients: recipesByProduct.get(p.id) ?? [],
70	  }));
71	
72	  return (
73	    <div className="w-full max-w-2xl">
74	      <h1 className="text-lg font-bold text-zinc-900">Kalkulator HPP — {business.name}</h1>
75	      <p className="mt-1 text-sm text-zinc-500">
76	        Pilih menu untuk melihat total HPP dari seluruh bahan di resepnya, lengkap dengan
77	        simulasi harga jual & margin.
78	      </p>
79	
80	      <HppCalculator menuItems={menuItems} />
81	    </div>
82	  );
83	}
