3	import { useMemo, useState } from "react";
4	
5	type Ingredient = { name: string; qty: number; unit: string; unitCost: number; lineCost: number };
6	type MenuItem = { id: string; name: string; price: number; cost: number; ingredients: Ingredient[] };
7	
8	function formatRupiah(value: number) {
9	  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
10	}
