12	export default function HppCalculator({ menuItems }: { menuItems: MenuItem[] }) {
13	  const [selectedId, setSelectedId] = useState(menuItems[0]?.id ?? "");
14	  const [trialPrice, setTrialPrice] = useState("");
15	  const [targetMargin, setTargetMargin] = useState("");
16	
17	  const selected = menuItems.find((m) => m.id === selectedId) ?? null;
18	
19	  const totalHpp = useMemo(
20	    () => selected?.ingredients.reduce((s, i) => s + i.lineCost, 0) ?? 0,
21	    [selected],
22	  );
23	
24	  const trialPriceNum = Number(trialPrice) || 0;
25	  const trialMargin = trialPriceNum > 0 ? trialPriceNum - totalHpp : null;
26	  const trialMarginPct = trialPriceNum > 0 ? Math.round((trialMargin! / trialPriceNum) * 100) : null;
27	
28	  const targetMarginNum = Number(targetMargin);
29	  const suggestedPrice =
30	    targetMargin !== "" && targetMarginNum >= 0 && targetMarginNum < 100
31	      ? Math.round(totalHpp / (1 - targetMarginNum / 100))
32	      : null;
33	
34	  return (
35	    <div className="mt-6 space-y-4">
36	      <div className="rounded-xl bg-white shadow-sm p-4">
37	        <label className="mb-1 block text-xs font-medium text-zinc-600">Pilih Menu</label>
38	        <select
39	          value={selectedId}
40	          onChange={(e) => setSelectedId(e.target.value)}
41	          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
42	        >
43	          {menuItems.length === 0 && <option value="">Belum ada menu/produk</option>}
44	          {menuItems.map((m) => (
45	            <option key={m.id} value={m.id}>
46	              {m.name}
47	            </option>
48	          ))}
49	        </select>
50	      </div>
51	
52	      {selected && (
53	        <>
54	          <div className="overflow-hidden rounded-xl bg-white shadow-sm">
55	            <div className="border-b border-zinc-100 px-4 py-3.5">
56	              <h2 className="text-sm font-bold text-zinc-900">Rincian Bahan — {selected.name}</h2>
57	            </div>
58	            {selected.ingredients.length > 0 ? (
59	              <div className="divide-y divide-zinc-100">
60	                {selected.ingredients.map((ing, i) => (
61	                  <div key={i} className="flex items-center justify-between px-4 py-2.5">
62	                    <span className="text-sm text-zinc-700">
63	                      {ing.name}{" "}
64	                      <span className="text-zinc-400">
65	                        ({ing.qty} {ing.unit})
66	                      </span>
67	                    </span>
68	                    <span className="text-sm font-medium text-zinc-900">
69	                      {formatRupiah(ing.lineCost)}
70	                    </span>
71	                  </div>
72	                ))}
73	              </div>
74	            ) : (
75	              <p className="px-4 py-6 text-center text-xs text-zinc-400">
76	                Menu ini belum punya resep. Tambahkan dulu di halaman Kelola Produk → Resep.
77	              </p>
78	            )}
79	            <div className="flex items-center justify-between border-t border-zinc-100 bg-zinc-50 px-4 py-3">
80	              <span className="text-sm font-bold text-zinc-900">Total HPP</span>
81	              <span className="text-sm font-bold text-brand-700">{formatRupiah(totalHpp)}</span>
82	            </div>
83	          </div>
84	
85	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
86	            <div className="rounded-xl bg-white shadow-sm p-4">
87	              <h2 className="text-sm font-bold text-zinc-900">Uji Harga Jual</h2>
88	              <p className="mt-0.5 text-[11px] text-zinc-400">Isi harga jual, lihat marginnya</p>
89	              <input
90	                type="number"
91	                min="0"
92	                value={trialPrice}
93	                onChange={(e) => setTrialPrice(e.target.value)}
94	                placeholder={String(selected.price)}
95	                className="mt-3 w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
96	              />
97	              {trialMargin !== null && (
98	                <p className="mt-2 text-xs text-zinc-500">
99	                  Margin: <span className="font-semibold text-zinc-900">{formatRupiah(trialMargin)}</span>{" "}
100	                  ({trialMarginPct}%)
101	                </p>
102	              )}
103	            </div>
104	
105	            <div className="rounded-xl bg-white shadow-sm p-4">
106	              <h2 className="text-sm font-bold text-zinc-900">Target Margin</h2>
107	              <p className="mt-0.5 text-[11px] text-zinc-400">Isi target %, lihat saran harga</p>
108	              <input
109	                type="number"
110	                min="0"
111	                max="99"
112	                value={targetMargin}
113	                onChange={(e) => setTargetMargin(e.target.value)}
114	                placeholder="mis. 30"
115	                className="mt-3 w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
116	              />
117	              {suggestedPrice !== null && (
118	                <p className="mt-2 text-xs text-zinc-500">
119	                  Saran harga jual:{" "}
120	                  <span className="font-semibold text-zinc-900">{formatRupiah(suggestedPrice)}</span>
121	                </p>
122	              )}
123	            </div>
124	          </div>
125	
126	          <p className="text-center text-[11px] text-zinc-400">
127	            Harga jual saat ini di produk: {formatRupiah(selected.price)} · HPP tersimpan:{" "}
128	            {formatRupiah(selected.cost)}
129	          </p>
130	        </>
131	      )}
132	    </div>
133	  );
134	}
