3	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
4	
5	export async function recalculateProductCost(supabase: SupabaseServerClient, productId: string) {
6	  const { data: items } = await supabase
7	    .from("product_recipes")
8	    .select("qty, ingredients(unit_cost)")
9	    .eq("product_id", productId);
10	
11	  const totalCost = (items ?? []).reduce((sum, item) => {
12	    const ingredient = item.ingredients as unknown as { unit_cost: number } | null;
13	    return sum + Number(ingredient?.unit_cost ?? 0) * Number(item.qty);
14	  }, 0);
15	
16	  await supabase.from("products").update({ cost: totalCost }).eq("id", productId);
17	}
18	
19	// Bahan baku dipakai di banyak resep produk — dipanggil setiap kali
20	// unit_cost sebuah bahan berubah (edit manual, pembelian lewat Catat
21	// Pengeluaran, atau Pembelian formal) supaya products.cost tidak basi.
22	export async function recalculateProductCostsForIngredient(
23	  supabase: SupabaseServerClient,
24	  ingredientId: string,
25	) {
26	  const { data: recipes } = await supabase
27	    .from("product_recipes")
28	    .select("product_id")
29	    .eq("ingredient_id", ingredientId);
30	
31	  const productIds = Array.from(new Set((recipes ?? []).map((r) => r.product_id)));
32	  for (const productId of productIds) {
33	    await recalculateProductCost(supabase, productId);
34	  }
35	}
